@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSubscription;

    protected override async Task OnInitializedAsync()
    {
        // Register callback so prerender can persist data into the page payload
        _persistSubscription = ApplicationState.RegisterOnPersisting(PersistEquipment);

        // If the data was already persisted during prerender, reuse it
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(_items), out var restored))
        {
            _items = restored;
        }
        else
        {
            // First render (prerender) — actually fetch data
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistEquipment()
    {
        ApplicationState.PersistAsJson(nameof(_items), _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistSubscription.Dispose();
    }
}

